window.MG_LAZY_DATA["data/lazy/resources/hpc-v26-045-77a86465696e7571.json"]={sha256:"77a86465696e7571a977a54e5c1d406c5aea4f9a8114e25d10f906255d09250b",value:{"sources":[{"id":"v26-case-29bc9b74199f0f85","url":"https://www.spec.org/cpu2017/Docs/runrules.html","title":"SPEC CPU run and reporting rules","titleEn":"SPEC CPU run and reporting rules","publisher":"SPEC","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"hpc-v26-045","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"hpc-v26-045","related":[{"id":"hpc-v26-046","referenceUrls":["https://kokkos.org/kokkos-core-wiki/ProgrammingGuide/ProgrammingModel.html"],"title":"Kokkos View：記憶體布局與存取跨度","titleEn":"Kokkos View: memory layouts and access strides","why":"用兩課的可觀察驗收條件比較模型邊界：交付量測清單、中位與範圍表及宣稱限制；1.8/2正確，所有六樣本保留、基準一致且沒有冒稱正式SPEC分數；請另一位學徒依交付件重新推導一組；未通過或資料不足必須明記，不以品牌或峰值取代證據。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver measurement manifests, medians and ranges, and limits on performance claims. Verify 1.8 and 2, retain all six samples, use the same baseline, and make no official SPEC-score claim. Have another learner derive one case from the handover; label failures or missing evidence without substituting brand names or peak rates.","difference":"畫3×4矩陣，依行與依列各寫線性索引；標連續j和連續i的工作分配；48/56正確，所有12邏輯元素保持相同且地址不越界。","differenceEn":"Draw all 3×4 indices in row and column order. Map work across consecutive i or j values. Verify offsets 48 and 56 with all 12 logical elements unchanged and in bounds.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["三次量測以中位數描述典型時間；同時保留全部樣本和範圍，不只挑最快一次；合成A時間[9,10,30]秒，B[8,9,10]秒；比較各中位數相對固定基準18秒的速度；名義式 18/10 = 1.8 median-based speedup；變更式 18/9 = 2 median-based speedup。數據與驗收門檻為原創教學情境，並非所列超級電腦或函式庫的實測規格。","row-major偏移i×C+j，column-major偏移j×R+i；同一邏輯矩陣可有不同實體跨度；合成R3、C4，元素(i1,j2)，每元素8bytes；求兩布局byte offset；名義式 (1*4+2)*8 = 48 byte offset；變更式 (2*3+1)*8 = 56 byte offset。數據與驗收門檻為原創教學情境，並非所列超級電腦或函式庫的實測規格。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Use the median of three runs to describe typical time, while retaining every sample and the range. Synthetic A times [9, 10, 30] and B times [8, 9, 10] seconds. Compare median speedups against one fixed 18-second baseline. Nominal 18/10 = 1.8 median-based speedup; changed 18/9 = 2 median-based speedup. Inputs and acceptance thresholds are original teaching scenarios, not measured specifications of the named systems or libraries.","Row-major offset is iC+j; column-major offset is jR+i. The same logical matrix can have different physical strides. Synthetic R = 3, C = 4, index (1, 2), and 8 bytes per element. Calculate both byte offsets. Nominal (1*4+2)*8 = 48 byte offset; changed (2*3+1)*8 = 56 byte offset. Inputs and acceptance thresholds are original teaching scenarios, not measured specifications of the named systems or libraries.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"hpc-v26-055","referenceUrls":["https://www.mpi-forum.org/docs/mpi-4.1/mpi41-report.pdf"],"title":"MPI RMA：視窗 epoch 與批次同步預算","titleEn":"MPI RMA: window epochs and batched synchronization","why":"用兩課的可觀察驗收條件比較模型邊界：交付量測清單、中位與範圍表及宣稱限制；1.8/2正確，所有六樣本保留、基準一致且沒有冒稱正式SPEC分數；請另一位學徒依交付件重新推導一組；未通過或資料不足必須明記，不以品牌或峰值取代證據。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver measurement manifests, medians and ranges, and limits on performance claims. Verify 1.8 and 2, retain all six samples, use the same baseline, and make no official SPEC-score claim. Have another learner derive one case from the handover; label failures or missing evidence without substituting brand names or peak rates.","difference":"以合成資料重建「MPI RMA：視窗 epoch 與批次同步預算」，能分離架構事實、模型假設與驗收證據。完成：交付 epoch 時序、讀寫依賴圖與每批成本表。","differenceEn":"Reconstruct MPI RMA: window epochs and batched synchronization with synthetic data; distinguish architecture facts, model assumptions and acceptance evidence. Complete: Deliver epoch timelines, read/write dependency graphs and batch cost tables.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["三次量測以中位數描述典型時間；同時保留全部樣本和範圍，不只挑最快一次；合成A時間[9,10,30]秒，B[8,9,10]秒；比較各中位數相對固定基準18秒的速度；名義式 18/10 = 1.8 median-based speedup；變更式 18/9 = 2 median-based speedup。數據與驗收門檻為原創教學情境，並非所列超級電腦或函式庫的實測規格。","把一千次更新拆為一千個 5 μs 同步加 0.2 μs 更新小格。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Use the median of three runs to describe typical time, while retaining every sample and the range. Synthetic A times [9, 10, 30] and B times [8, 9, 10] seconds. Compare median speedups against one fixed 18-second baseline. Nominal 18/10 = 1.8 median-based speedup; changed 18/9 = 2 median-based speedup. Inputs and acceptance thresholds are original teaching scenarios, not measured specifications of the named systems or libraries.","Represent one thousand updates as 5 μs synchronization plus 0.2 μs transfer cells.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-4295d5a0558ad030","url":"https://kokkos.org/kokkos-core-wiki/ProgrammingGuide/ProgrammingModel.html","title":"Kokkos Programming Model","titleEn":"Kokkos Programming Model","publisher":"Kokkos development team","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-245d4116a6090a19","url":"https://www.mpi-forum.org/docs/mpi-4.1/mpi41-report.pdf","title":"MPI 4.1 standard","titleEn":"MPI 4.1 standard","publisher":"MPI Forum","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
